#include "ksStateParameterEditTask.h"
#include <iostream>
#include <vector>
#include <utility>
#include <stdexcept>
using T=ks::StateParameterEditTask;using M=ks::StateFieldMapTask;using C=T::Child;using W=T::Write;
void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;auto verify=[&](bool direct,unsigned p,unsigned v,M::Outcome mapping,uint32_t mappedField,unsigned mappedValue,unsigned translatedField,unsigned type,unsigned inhibit,unsigned notificationMode,unsigned notificationField,bool display){T task(direct?T::Entry::Internal:T::Entry::Public,p,v,0xa12345);unsigned reads=0,clocks=0;std::vector<C> children;std::vector<std::pair<W,unsigned>> writes;bool mappingUsed=false;
 auto read=[&](T::Read r)->uint32_t{++reads;switch(r){case T::Read::Field:check(task.parameter()==(direct?p:uint8_t(p+128)),"Banked parameter differs");return translatedField;case T::Read::Type:check(task.field()==translatedField,"Type field differs");return type;case T::Read::Inhibit:return inhibit;case T::Read::CurrentBase:return 0xffa30000;case T::Read::LiveBase:return 0xffa31000;case T::Read::NotificationMode:return notificationMode;case T::Read::NotificationField:return notificationField;}return 0;};
 auto write=[&](W w,uint8_t value){writes.emplace_back(w,value);};while(!task.complete()){if(task.awaitingChild()){children.push_back(task.child());mappingUsed|=task.child()==C::MapControl;check(task.resumeChild(mapping,mappedField,mapping==M::Outcome::Unmapped?v:mappedValue,display),"Child rejected");continue;}const auto cost=task.nextClocks(),before=reads;const auto beforeWrites=writes.size();check(cost>0,"Edit stalled");check(!task.advanceBefore(cost-1,read,write)&&reads==before&&writes.size()==beforeWrites,"Edit read/write early");check(task.advanceBefore(cost,read,write)==cost,"Edit admission differs");clocks+=cost;}
 std::vector<C> expectedChildren;std::vector<std::pair<W,unsigned>> expectedWrites;unsigned expectedReads=0,expectedClocks=0;bool proceed=direct;unsigned output=v;uint32_t field=translatedField;
 if(!direct){expectedClocks=6;if(p>127)expectedClocks+=17;else{expectedChildren.push_back(C::MapControl);expectedClocks+=23; // call20 + admission3
   if(mapping==M::Outcome::Unmapped){expectedClocks+=3;proceed=true;}else{expectedClocks+=3;if(mapping==M::Outcome::AboveLimit)expectedClocks+=17;else{proceed=true;field=mappedField;output=mappedValue;}}}}
 bool notify=false;const bool mapped=mappingUsed&&mapping!=M::Outcome::Unmapped;
 if(proceed){if(!mapped){expectedClocks+=45;expectedReads+=2;if(type>=126){expectedWrites={{W::Global,output},{W::GlobalMirror,output}};expectedClocks+=33;notify=true;}else{expectedClocks+=15;++expectedReads;if(inhibit)expectedClocks+=17;else{expectedChildren.push_back(C::BindCurrent);expectedClocks+=82;}}}
  if(mapped||type<126&&!inhibit){expectedReads+=2;expectedWrites={{W::Current,output},{W::Live,output}};expectedChildren.push_back(C::ExpandFields);expectedChildren.push_back(C::RebindMode);expectedChildren.push_back(C::MarkDirty);expectedClocks+=136;notify=true;}
  if(notify){expectedClocks+=15;++expectedReads;if(notificationMode){expectedClocks+=18;++expectedReads;if(uint8_t(field)==notificationField){expectedChildren.push_back(C::RefreshDisplay);expectedClocks+=20;}else expectedClocks+=3;}else{expectedChildren.push_back(C::ProbeDisplay);expectedClocks+=23;if(display){expectedChildren.push_back(C::RefreshDisplay);expectedClocks+=20;}}expectedWrites.emplace_back(W::Edited,1);expectedClocks+=32;}}
 if(clocks!=expectedClocks){std::cerr<<"clocks="<<clocks<<" expected="<<expectedClocks<<" direct="<<direct<<" p="<<p<<" mapping="<<unsigned(mapping)<<" type="<<type<<" inhibit="<<inhibit<<" notify="<<notificationMode<<'\n';throw std::runtime_error("Edit schedule differs");}
 if(reads!=expectedReads||children!=expectedChildren||writes!=expectedWrites){std::cerr<<"direct="<<direct<<" p="<<p<<" v="<<v<<" mapping="<<unsigned(mapping)<<" reads="<<reads<<" expected="<<expectedReads<<" children="<<children.size()<<" expected="<<expectedChildren.size()<<" writes="<<writes.size()<<" expected="<<expectedWrites.size()<<std::endl;throw std::runtime_error("Edit reads/writes/child order differs");}check(!task.resumeChild()&&!task.advanceBefore(999,read,write),"Completed edit restarted");++cases;};
 for(bool direct:{false,true})for(unsigned p=0;p<256;++p)for(unsigned v=0;v<256;++v)for(auto mapping:{M::Outcome::Unmapped,M::Outcome::EqualLimit,M::Outcome::AboveLimit,M::Outcome::Packed})verify(direct,p,v,mapping,0x100+(v&255),v^0xaa,(p*17+v*23)&255,(p+v)&255,p&1,(p+v)&1,v,p&2);
 for(unsigned type=0;type<256;++type)for(unsigned inhibit=0;inhibit<256;++inhibit)for(unsigned notificationMode:{0u,1u,255u})for(bool display:{false,true})verify(true,255,127,M::Outcome::Unmapped,0,0,255,type,inhibit,notificationMode,255,display);
 std::cout<<"PASS: "<<cases<<" full edit semantics, all byte IDs/values/types/inhibits, mapper outcomes/context, global and live mirrors, ordered native children, notification branches and exact read/write/clocks\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
